<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Workboard</title>
    <link rel="stylesheet" href="/styles.css">
    <script type="module" src="/client.js"></script>
  </head>
  <body>
    <main class="container">
      <header class="topbar">
        <a class="brand" href="/">Workboard</a>
      </header>
      <section id="app" aria-live="polite"></section>
    </main>
  </body>
</html>
:root {
  color: #202936;
  background: #f5f7fa;
  font: 16px/1.5 system-ui, sans-serif;
}

* { box-sizing: border-box; }
body { margin: 0; }
.container { max-width: 760px; margin: 0 auto; padding: 0 24px 48px; }
.topbar { padding: 22px 0; border-bottom: 1px solid #dce2e9; margin-bottom: 32px; }
.brand { color: #1d4ed8; font-size: 1.2rem; font-weight: 700; text-decoration: none; }
h1 { margin: 0 0 24px; font-size: 2rem; }
.create-form { display: grid; gap: 8px; max-width: 420px; margin-bottom: 28px; }
label { font-weight: 600; }
input, button, select { font: inherit; }
input, select { padding: 10px 12px; border: 1px solid #aeb9c7; border-radius: 6px; background: white; }
button { width: fit-content; padding: 9px 14px; border: 0; border-radius: 6px; background: #2458c6; color: white; cursor: pointer; }
button:hover { background: #1946a5; }
button:disabled, input:disabled { cursor: not-allowed; opacity: .6; }
button:focus-visible, input:focus-visible, a:focus-visible { outline: 3px solid #f59e0b; outline-offset: 2px; }
.project-list { display: grid; gap: 10px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px; border: 1px solid #dce2e9; border-radius: 8px; background: white; }
.project-details, .project-actions { display: flex; align-items: center; gap: 12px; }
.project-details { flex-direction: column; align-items: flex-start; }
.project-summary { color: #586575; font-size: .9rem; }
.project-actions { flex-wrap: wrap; justify-content: flex-end; }
.archived-status { font-weight: 600; color: #586575; }
.alert { color: #a32222; font-weight: 600; }
